#!/usr/bin/env python3
"""
Round 176b (culprits-tiles-more), 5 October 2026.

Global Energy Monitor's download packed into gem/coal/download/, and
scripts/gem_coal.py with open and closed mines, ownership chains as lines and
the parent companies ranked by methane. Whole files, each written only if it
differs. Run from the repository root.
"""
import base64, pathlib

FILES = {
    "scripts/gem_coal.py": "",
    "gem/coal/download/README.md": "",
    "gem/coal/download/Coal Mine Boundaries and Methane Sources - version 1.0.2.zip": "",
    "gem/coal/download/Global Coal Mine Tracker, August 2026.xlsx": "",
    "gem/coal/download/Global Energy Ownership Tracker September 2026 V2 - Coal Mine Ownership.zip": "",
}


def main():
    for name, data in FILES.items():
        p = pathlib.Path(name)
        new = base64.b64decode(data)
        if p.exists() and p.read_bytes() == new:
            print(f"round176b_tiles: {name} already up to date")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(new)
        print(f"round176b_tiles: wrote {name}")


if __name__ == "__main__":
    main()
